MODELAGEM_LOGICO_ALGORITMA.CODIGO_FONTE:
void verificarSenha() {
  if (cofreAberto) {
    return;
  }
  if (senhaDigitada == senhaCorreta) {
    abrirCofre();
  } else {
    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print("SENHA INVALIDA");
    lcd.setCursor(0, 1);
    lcd.print("TENTE NOVAMENTE");
    delay(2000);
    mostrarTelaInicial();
  }
}
